	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/devices/{id}", wrapper.UpdateDevice)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/devices/{id}/status", wrapper.SetDeviceStatus)
